// ===== Admin Pages =====
(function() {
var A = window.App;
var ic = A.icon, fp = A.formatPrice, fd = A.formatDate, SB = A.StatusBadge;

// ===== Admin Login =====
A.pages.adminLogin = function() {
  var content='<div class="min-h-screen bg-surface flex items-center justify-center p-4"><div class="bg-white rounded-xl border border-border p-8 w-full max-w-md"><div class="text-center mb-8"><h1 class="text-3xl font-bold mb-2">Admin Login</h1><p class="text-text-secondary">Đăng nhập vào trang quản trị</p></div><form id="admin-login-form" class="space-y-4"><div><label class="label">Tên đăng nhập</label><input class="input" id="admin-username" required placeholder="admin" /></div><div><label class="label">Mật khẩu</label><input class="input" id="admin-password" type="password" required placeholder="••••••••" /></div><button type="submit" class="btn btn-default w-full btn-lg" id="admin-login-btn">Đăng nhập</button></form></div></div>';
  A.renderFullPage(content, function(){
    document.getElementById('admin-login-form').addEventListener('submit',function(e){e.preventDefault();
      var btn=document.getElementById('admin-login-btn');btn.disabled=true;btn.textContent='Đang đăng nhập...';
      setTimeout(function(){A.setCurrentUser({id:'staff1',name:'Nguyễn Quản Trị',username:'admin',email:'admin@fashionstore.com',phone:'0901111111',role:'admin'});A.toast.success('Đăng nhập thành công');A.navigateTo('/admin');},1000);
    });
  });
};

// ===== Analytics =====
A.pages.analytics = function() {
  var totalRevenue=A.mockOrders.reduce(function(s,o){return s+o.total;},0);
  var totalOrders=A.mockOrders.length;
  var totalProducts=A.mockProducts.length;
  var lowStock=A.mockProducts.reduce(function(c,p){return c+p.variants.filter(function(v){return v.stock<10;}).length;},0);

  var content='<div><div class="mb-6"><h1 class="text-3xl font-bold">Tổng quan</h1><p class="text-text-secondary mt-2">Tổng quan hoạt động kinh doanh</p></div>'+
    '<div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">'+
    '<div class="card"><div class="card-content pt-6"><div class="flex items-center justify-between"><div><p class="text-sm text-text-secondary">Tổng doanh thu</p><p class="text-2xl font-bold">'+fp(totalRevenue)+'</p></div><div class="w-12 h-12 bg-green-50 rounded-full flex items-center justify-center">'+ic('dollar-sign','w-6 h-6 text-success')+'</div></div></div></div>'+
    '<div class="card"><div class="card-content pt-6"><div class="flex items-center justify-between"><div><p class="text-sm text-text-secondary">Tổng đơn hàng</p><p class="text-2xl font-bold">'+totalOrders+'</p></div><div class="w-12 h-12 bg-blue-50 rounded-full flex items-center justify-center">'+ic('shopping-cart','w-6 h-6 text-info')+'</div></div></div></div>'+
    '<div class="card"><div class="card-content pt-6"><div class="flex items-center justify-between"><div><p class="text-sm text-text-secondary">Tổng sản phẩm</p><p class="text-2xl font-bold">'+totalProducts+'</p></div><div class="w-12 h-12 bg-purple-50 rounded-full flex items-center justify-center">'+ic('package','w-6 h-6 text-purple-600')+'</div></div></div></div>'+
    '<div class="card"><div class="card-content pt-6"><div class="flex items-center justify-between"><div><p class="text-sm text-text-secondary">Sắp hết hàng</p><p class="text-2xl font-bold">'+lowStock+'</p></div><div class="w-12 h-12 bg-red-50 rounded-full flex items-center justify-center">'+ic('alert-triangle','w-6 h-6 text-error')+'</div></div></div></div></div>'+
    '<div class="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-8"><div class="card"><div class="card-header"><h3 class="card-title">Doanh thu theo tháng</h3></div><div class="card-content"><canvas id="revenue-chart" height="250"></canvas></div></div><div class="card"><div class="card-header"><h3 class="card-title">Phân bổ đơn hàng</h3></div><div class="card-content"><canvas id="orders-chart" height="250"></canvas></div></div></div>'+
    '<div class="card"><div class="card-header"><h3 class="card-title">Đơn hàng gần đây</h3></div><div class="card-content"><div class="table-wrapper"><table class="data-table"><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Ngày</th><th>Tổng tiền</th><th>Trạng thái</th></tr></thead><tbody>'+A.mockOrders.slice(0,5).map(function(o){return '<tr><td class="font-mono">'+o.orderNumber+'</td><td>'+o.customerName+'</td><td>'+fd(o.createdAt)+'</td><td class="font-semibold">'+fp(o.total)+'</td><td>'+SB(o.status)+'</td></tr>';}).join('')+'</tbody></table></div></div></div></div>';

  A.renderAdmin(content, function(){
    if(window.Chart){
      var rc=document.getElementById('revenue-chart');
      if(rc) new Chart(rc.getContext('2d'),{type:'line',data:{labels:['T1','T2','T3','T4','T5','T6'],datasets:[{label:'Doanh thu',data:[15000000,22000000,18000000,25000000,30000000,28000000],borderColor:'#E11D48',backgroundColor:'rgba(225,29,72,0.1)',tension:0.4,fill:true}]},options:{responsive:true,plugins:{legend:{display:false}},scales:{y:{ticks:{callback:function(v){return(v/1000000)+'M';}}}}}});
      var oc=document.getElementById('orders-chart');
      if(oc) new Chart(oc.getContext('2d'),{type:'doughnut',data:{labels:['Online','Tại quầy'],datasets:[{data:[A.mockOrders.filter(function(o){return o.type==='online';}).length,A.mockOrders.filter(function(o){return o.type==='pos';}).length],backgroundColor:['#E11D48','#111827']}]},options:{responsive:true}});
    }
  });
};

// ===== Products List =====
A.pages.productsList = function(){
  function rows(prods){return prods.map(function(p){var ts=p.variants.reduce(function(s,v){return s+v.stock;},0);return '<tr><td><img src="'+p.images[0]+'" alt="" class="w-12 h-12 object-cover rounded-lg" /></td><td class="font-mono text-sm">'+p.code+'</td><td class="font-medium">'+p.name+'</td><td>'+p.category+'</td><td>'+fp(p.salePrice||p.basePrice)+'</td><td><span class="'+(ts<10?'text-error font-semibold':'')+'">'+ts+'</span></td><td><span class="badge '+(p.status==='active'?'badge-default':'badge-outline')+'">'+(p.status==='active'?'Hoạt động':'Ngừng')+'</span></td><td class="text-right"><div class="flex justify-end gap-2"><a href="#/admin/products/edit/'+p.id+'" class="btn btn-outline btn-sm">'+ic('pencil','w-4 h-4')+'</a></div></td></tr>';}).join('');}
  var content='<div><div class="flex justify-between items-center mb-6"><div><h1 class="text-3xl font-bold">Sản phẩm</h1><p class="text-text-secondary mt-2">'+A.mockProducts.length+' sản phẩm</p></div><a href="#/admin/products/add" class="btn btn-default">'+ic('plus','w-4 h-4')+' Thêm sản phẩm</a></div><div class="card"><div class="card-header"><div class="flex justify-between items-center"><h3 class="card-title">Danh sách</h3><div class="relative">'+ic('search','w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-text-secondary')+'<input class="input pl-10 w-80" placeholder="Tìm kiếm..." id="admin-product-search" /></div></div></div><div class="card-content"><div class="table-wrapper"><table class="data-table"><thead><tr><th>Ảnh</th><th>Mã</th><th>Tên</th><th>Danh mục</th><th>Giá</th><th>Tồn</th><th>TT</th><th class="text-right">Thao tác</th></tr></thead><tbody id="admin-products-tbody">'+rows(A.mockProducts)+'</tbody></table></div></div></div></div>';
  A.renderAdmin(content,function(){
    document.getElementById('admin-product-search').addEventListener('input',function(e){
      var t=e.target.value.toLowerCase();
      var f=A.mockProducts.filter(function(p){return p.name.toLowerCase().indexOf(t)>=0||p.code.toLowerCase().indexOf(t)>=0;});
      document.getElementById('admin-products-tbody').innerHTML=rows(f);A.initIcons();
    });
  });
};

// ===== Add Product =====
A.pages.addProduct = function(){
  var content='<div><div class="mb-6"><a href="#/admin/products" class="text-primary hover:underline mb-4 inline-block">← Quay lại</a><h1 class="text-3xl font-bold">Thêm sản phẩm mới</h1></div><form id="add-product-form"><div class="grid grid-cols-1 lg:grid-cols-3 gap-6"><div class="lg:col-span-2 space-y-6"><div class="card"><div class="card-header"><h3 class="card-title">Thông tin cơ bản</h3></div><div class="card-content space-y-4"><div class="grid grid-cols-2 gap-4"><div><label class="label">Mã sản phẩm *</label><input class="input" required /></div><div><label class="label">Danh mục *</label><select class="custom-select" required><option value="">Chọn</option>'+A.mockCategories.filter(function(c){return !c.parentId;}).map(function(c){return '<option>'+c.name+'</option>';}).join('')+'</select></div></div><div><label class="label">Tên sản phẩm *</label><input class="input" required /></div><div><label class="label">Mô tả</label><textarea class="input" rows="4"></textarea></div><div class="grid grid-cols-2 gap-4"><div><label class="label">Giá gốc *</label><input class="input" type="number" required /></div><div><label class="label">Giá sale</label><input class="input" type="number" /></div></div></div></div></div><div class="space-y-6"><div class="card"><div class="card-header"><h3 class="card-title">Hành động</h3></div><div class="card-content space-y-3"><button type="submit" class="btn btn-default w-full">'+ic('save','w-4 h-4')+' Lưu</button><a href="#/admin/products" class="btn btn-outline w-full">Hủy</a></div></div></div></div></form></div>';
  A.renderAdmin(content,function(){document.getElementById('add-product-form').addEventListener('submit',function(e){e.preventDefault();A.toast.success('Đã thêm sản phẩm');A.navigateTo('/admin/products');});});
};

// ===== Edit Product =====
A.pages.editProduct = function(productId){
  var p=A.mockProducts.find(function(x){return x.id===productId;});
  if(!p){A.renderAdmin('<div class="text-center py-12"><h2 class="text-2xl">Không tìm thấy</h2><a href="#/admin/products" class="btn btn-default mt-4">Quay lại</a></div>');return;}
  var content='<div><div class="mb-6"><a href="#/admin/products" class="text-primary hover:underline mb-4 inline-block">← Quay lại</a><h1 class="text-3xl font-bold">Chỉnh sửa: '+p.name+'</h1></div><form id="edit-product-form"><div class="grid grid-cols-1 lg:grid-cols-3 gap-6"><div class="lg:col-span-2 space-y-6"><div class="card"><div class="card-header"><h3 class="card-title">Thông tin cơ bản</h3></div><div class="card-content space-y-4"><div class="grid grid-cols-2 gap-4"><div><label class="label">Mã SP</label><input class="input" value="'+p.code+'" /></div><div><label class="label">Danh mục</label><select class="custom-select">'+A.mockCategories.filter(function(c){return !c.parentId;}).map(function(c){return '<option '+(c.name===p.category?'selected':'')+'>'+c.name+'</option>';}).join('')+'</select></div></div><div><label class="label">Tên</label><input class="input" value="'+p.name+'" /></div><div><label class="label">Mô tả</label><textarea class="input" rows="4">'+p.description+'</textarea></div><div class="grid grid-cols-2 gap-4"><div><label class="label">Giá gốc</label><input class="input" type="number" value="'+p.basePrice+'" /></div><div><label class="label">Giá sale</label><input class="input" type="number" value="'+(p.salePrice||'')+'" /></div></div></div></div><div class="card"><div class="card-header"><h3 class="card-title">Biến thể ('+p.variants.length+')</h3></div><div class="card-content"><div class="table-wrapper"><table class="data-table"><thead><tr><th>SKU</th><th>Size</th><th>Màu</th><th>Tồn kho</th></tr></thead><tbody>'+p.variants.map(function(v){return '<tr><td class="font-mono text-sm">'+v.sku+'</td><td>'+v.size+'</td><td>'+v.color+'</td><td>'+v.stock+'</td></tr>';}).join('')+'</tbody></table></div></div></div></div><div class="space-y-6"><div class="card"><div class="card-header"><h3 class="card-title">Hành động</h3></div><div class="card-content space-y-3"><button type="submit" class="btn btn-default w-full">'+ic('save','w-4 h-4')+' Lưu</button><a href="#/admin/products" class="btn btn-outline w-full">Hủy</a></div></div></div></div></form></div>';
  A.renderAdmin(content,function(){document.getElementById('edit-product-form').addEventListener('submit',function(e){e.preventDefault();A.toast.success('Đã cập nhật');A.navigateTo('/admin/products');});});
};

// ===== Orders =====
A.pages.adminOrders = function(){
  function rows(orders){return orders.map(function(o){return '<tr><td class="font-mono">'+o.orderNumber+'</td><td><span class="badge '+(o.type==='online'?'badge-default':'badge-outline')+'">'+(o.type==='online'?'Online':'POS')+'</span></td><td>'+o.customerName+'</td><td>'+fd(o.createdAt)+'</td><td class="font-semibold">'+fp(o.total)+'</td><td>'+SB(o.status)+'</td><td class="text-right"><a href="#/admin/orders/'+o.id+'" class="btn btn-outline btn-sm">'+ic('eye','w-4 h-4')+'</a></td></tr>';}).join('');}
  var content='<div><div class="mb-6"><h1 class="text-3xl font-bold">Đơn hàng</h1></div><div class="card"><div class="card-header"><div class="flex justify-between items-center"><h3 class="card-title">Danh sách</h3><div class="relative">'+ic('search','w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-text-secondary')+'<input class="input pl-10 w-80" placeholder="Tìm kiếm..." id="admin-order-search" /></div></div></div><div class="card-content"><div class="table-wrapper"><table class="data-table"><thead><tr><th>Mã đơn</th><th>Loại</th><th>Khách</th><th>Ngày</th><th>Tổng</th><th>TT</th><th class="text-right">Thao tác</th></tr></thead><tbody id="admin-orders-tbody">'+rows(A.mockOrders)+'</tbody></table></div></div></div></div>';
  A.renderAdmin(content,function(){document.getElementById('admin-order-search').addEventListener('input',function(e){var t=e.target.value.toLowerCase();var f=A.mockOrders.filter(function(o){return o.orderNumber.toLowerCase().indexOf(t)>=0||o.customerName.toLowerCase().indexOf(t)>=0;});document.getElementById('admin-orders-tbody').innerHTML=rows(f);A.initIcons();});});
};

A.pages.adminOrderDetail = function(orderId){
  var o=A.mockOrders.find(function(x){return x.id===orderId;});
  if(!o){A.renderAdmin('<div class="text-center py-12"><h2 class="text-2xl">Không tìm thấy</h2></div>');return;}
  var statusOpts=['pending','confirmed','shipping','completed','cancelled'];
  var statusLabels={pending:'Chờ xử lý',confirmed:'Đã xác nhận',shipping:'Đang giao',completed:'Hoàn thành',cancelled:'Đã hủy'};
  var content='<div><div class="mb-6"><a href="#/admin/orders" class="text-primary hover:underline mb-4 inline-block">← Quay lại</a><h1 class="text-3xl font-bold">Đơn hàng '+o.orderNumber+'</h1></div><div class="grid grid-cols-1 lg:grid-cols-3 gap-6"><div class="lg:col-span-2"><div class="card"><div class="card-header"><h3 class="card-title">Sản phẩm</h3></div><div class="card-content"><div class="table-wrapper"><table class="data-table"><thead><tr><th>Sản phẩm</th><th>Biến thể</th><th>SL</th><th>Đơn giá</th><th>Thành tiền</th></tr></thead><tbody>'+o.items.map(function(i){return '<tr><td><div class="flex items-center gap-3"><img src="'+i.image+'" class="w-12 h-12 object-cover rounded-lg" /><span class="font-medium">'+i.productName+'</span></div></td><td>'+i.variantLabel+'</td><td>'+i.quantity+'</td><td>'+fp(i.price)+'</td><td class="font-semibold">'+fp(i.price*i.quantity)+'</td></tr>';}).join('')+'</tbody></table></div><div class="text-right mt-6 pt-4 border-t border-border"><p class="text-2xl font-bold text-accent">Tổng: '+fp(o.total)+'</p></div></div></div></div><div class="space-y-6"><div class="card"><div class="card-header"><h3 class="card-title">Cập nhật trạng thái</h3></div><div class="card-content space-y-4"><div>'+SB(o.status)+'</div><select class="custom-select" id="admin-order-status">'+statusOpts.map(function(s){return '<option value="'+s+'" '+(s===o.status?'selected':'')+'>'+statusLabels[s]+'</option>';}).join('')+'</select><button class="btn btn-default w-full" id="update-order-status">Cập nhật</button></div></div><div class="card"><div class="card-header"><h3 class="card-title">Khách hàng</h3></div><div class="card-content text-sm space-y-2"><p class="font-medium">'+o.customerName+'</p><p class="text-text-secondary">'+o.customerPhone+'</p><p class="text-text-secondary mt-2">'+o.shippingAddress.address+'</p></div></div></div></div></div>';
  A.renderAdmin(content,function(){document.getElementById('update-order-status').addEventListener('click',function(){o.status=document.getElementById('admin-order-status').value;A.toast.success('Đã cập nhật');A.pages.adminOrderDetail(orderId);});});
};

// ===== Categories =====
A.pages.adminCategories = function(){
  var cats=A.categories;
  function rows(){return cats.map(function(c){var parent=cats.find(function(p){return p.id===c.parentId;});return '<tr><td class="font-medium">'+c.name+'</td><td class="font-mono text-sm text-text-secondary">'+c.slug+'</td><td>'+(parent?parent.name:'—')+'</td><td>'+c.isVisible+'</td></tr>';}).join('');}
  var content='<div><div class="flex justify-between items-center mb-6"><div><h1 class="text-3xl font-bold">Danh mục</h1><p class="text-text-secondary mt-2">'+cats.length+' danh mục</p></div><button class="btn btn-default" id="add-cat-btn">'+ic('plus','w-4 h-4')+' Thêm danh mục</button></div><div class="card"><div class="card-content"><div class="table-wrapper"><table class="data-table"><thead><tr><th>Tên</th><th>Slug</th><th>Danh mục cha</th><th>Hiển thị</th></tr></thead><tbody>'+rows()+'</tbody></table></div></div></div></div>';
  A.renderAdmin(content,function(){
    document.getElementById('add-cat-btn').addEventListener('click',function(){
      var dc='<div class="dialog-header"><h3 class="dialog-title">Thêm danh mục</h3></div><div class="space-y-4"><div><label class="label">Tên *</label><input class="input" id="nc-name" /></div><div><label class="label">Slug</label><input class="input" id="nc-slug" /></div></div><div class="dialog-footer"><button class="btn btn-outline" data-close>Hủy</button><button class="btn btn-default" id="nc-save">Thêm</button></div>';
      var dlg=A.showDialog(dc,{maxWidth:'max-w-lg'});
      dlg.element.querySelector('#nc-save').addEventListener('click',function(){var name=dlg.element.querySelector('#nc-name').value;if(!name){A.toast.error('Nhập tên');return;}var slug=dlg.element.querySelector('#nc-slug').value||name.toLowerCase().replace(/\s+/g,'-');cats.push({id:'cat'+Date.now(),name:name,slug:slug,isVisible:true});dlg.close();A.toast.success('Đã thêm');A.pages.adminCategories();});
    });
  });
};

// ===== Customers =====
A.pages.adminCustomers = function(){
  function rows(custs){return custs.map(function(c){return '<tr><td class="font-medium">'+c.name+'</td><td>'+c.email+'</td><td>'+c.phone+'</td><td>'+c.totalOrders+'</td><td class="font-semibold">'+fp(c.totalSpent)+'</td><td>'+fd(c.createdAt)+'</td><td class="text-right"><button class="btn btn-outline btn-sm" data-view-cust="'+c.id+'">'+ic('eye','w-4 h-4')+'</button></td></tr>';}).join('');}
  var content='<div><div class="mb-6"><h1 class="text-3xl font-bold">Khách hàng</h1><p class="text-text-secondary mt-2">'+A.customers.length+' khách hàng</p></div><div class="card"><div class="card-header"><div class="flex justify-between items-center"><h3 class="card-title">Danh sách</h3><div class="relative">'+ic('search','w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-text-secondary')+'<input class="input pl-10 w-80" placeholder="Tìm kiếm..." id="admin-cust-search" /></div></div></div><div class="card-content"><div class="table-wrapper"><table class="data-table"><thead><tr><th>Tên</th><th>Email</th><th>SĐT</th><th>Đơn hàng</th><th>Tổng chi</th><th>Ngày tham gia</th><th class="text-right">Thao tác</th></tr></thead><tbody id="admin-custs-tbody">'+rows(A.customers)+'</tbody></table></div></div></div></div>';
  A.renderAdmin(content,function(){
    document.getElementById('admin-cust-search').addEventListener('input',function(e){var t=e.target.value.toLowerCase();var f=A.customers.filter(function(c){return c.name.toLowerCase().indexOf(t)>=0||c.email.toLowerCase().indexOf(t)>=0;});document.getElementById('admin-custs-tbody').innerHTML=rows(f);A.initIcons();bindCustView();});
    function bindCustView(){document.querySelectorAll('[data-view-cust]').forEach(function(b){b.addEventListener('click',function(){var c=A.customers.find(function(x){return x.id===b.dataset.viewCust;});if(!c)return;var dc='<div class="dialog-header"><h3 class="dialog-title">'+c.name+'</h3><p class="dialog-description">'+c.email+' · '+c.phone+'</p></div><div class="grid grid-cols-2 gap-4 mb-4"><div class="bg-surface p-4 rounded-lg text-center"><p class="text-2xl font-bold">'+c.totalOrders+'</p><p class="text-sm text-text-secondary">Đơn hàng</p></div><div class="bg-surface p-4 rounded-lg text-center"><p class="text-2xl font-bold">'+fp(c.totalSpent)+'</p><p class="text-sm text-text-secondary">Tổng chi</p></div></div>';A.showDialog(dc,{maxWidth:'max-w-lg'});});});}
    bindCustView();
  });
};

// ===== Inventory =====
A.pages.inventory = function(){
  var allVariants=[];A.products.forEach(function(p){p.variants.forEach(function(v){allVariants.push({sku:v.sku,size:v.size,color:v.color,stock:v.stock,productName:p.name,productCode:p.code});});});
  function invRows(vars){return vars.map(function(v){var st=v.stock===0?'Hết hàng':v.stock<10?'Sắp hết':'Còn hàng';var cls=v.stock===0?'badge-destructive':v.stock<10?'badge-default':'badge-default';return '<tr><td class="font-mono text-sm">'+v.productCode+'</td><td>'+v.productName+'</td><td class="font-mono text-sm">'+v.sku+'</td><td>'+v.size+'</td><td>'+v.color+'</td><td><span class="text-lg">'+v.stock+'</span></td><td><span class="badge '+cls+'">'+st+'</span></td></tr>';}).join('');}
  var content='<div><div class="flex justify-between items-center mb-6"><div><h1 class="text-3xl font-bold">Quản lý kho</h1></div></div><div class="tabs-list mb-6"><button class="tab-trigger active" data-tab="inventory">Tồn kho</button><button class="tab-trigger" data-tab="logs">Lịch sử</button></div><div class="tab-content active" id="tab-inventory"><div class="card"><div class="card-header"><div class="flex justify-between items-center"><h3 class="card-title">Danh sách tồn kho</h3><div class="relative">'+ic('search','w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-text-secondary')+'<input class="input pl-10 w-80" placeholder="Tìm kiếm..." id="inv-search" /></div></div></div><div class="card-content"><div class="table-wrapper"><table class="data-table"><thead><tr><th>Mã SP</th><th>Tên</th><th>SKU</th><th>Size</th><th>Màu</th><th>Tồn</th><th>TT</th></tr></thead><tbody id="inv-tbody">'+invRows(allVariants)+'</tbody></table></div></div></div></div><div class="tab-content" id="tab-logs"><div class="card"><div class="card-header"><h3 class="card-title">Lịch sử giao dịch ('+A.inventoryLogs.length+')</h3></div><div class="card-content"><div class="table-wrapper"><table class="data-table"><thead><tr><th>Ngày</th><th>Loại</th><th>SP</th><th>Biến thể</th><th>SL</th><th>Lý do</th><th>NV</th></tr></thead><tbody>'+A.inventoryLogs.map(function(l){var typeBadge=l.type==='stock-in'?'<span class="badge bg-success text-white">Nhập</span>':l.type==='stock-out'?'<span class="badge badge-destructive">Xuất</span>':'<span class="badge badge-outline">Điều chỉnh</span>';return '<tr><td>'+fd(l.createdAt)+'</td><td>'+typeBadge+'</td><td>'+l.productName+'</td><td>'+l.variantLabel+'</td><td><span class="'+(l.quantity>0?'text-success':'text-error')+'">'+(l.quantity>0?'+':'')+l.quantity+'</span></td><td>'+l.reason+'</td><td>'+l.staffName+'</td></tr>';}).join('')+'</tbody></table></div></div></div></div></div>';
  A.renderAdmin(content,function(){
    document.querySelectorAll('.tab-trigger').forEach(function(t){t.addEventListener('click',function(){document.querySelectorAll('.tab-trigger').forEach(function(x){x.classList.remove('active');});document.querySelectorAll('.tab-content').forEach(function(x){x.classList.remove('active');});t.classList.add('active');document.getElementById('tab-'+t.dataset.tab).classList.add('active');});});
    document.getElementById('inv-search').addEventListener('input',function(e){var t=e.target.value.toLowerCase();var f=allVariants.filter(function(v){return v.productName.toLowerCase().indexOf(t)>=0||v.productCode.toLowerCase().indexOf(t)>=0||v.sku.toLowerCase().indexOf(t)>=0;});document.getElementById('inv-tbody').innerHTML=invRows(f);});
  });
};

// ===== POS =====
A.pages.pos = function(){
  var content='<div><div class="mb-6"><h1 class="text-3xl font-bold">Bán hàng tại quầy</h1></div><div class="grid grid-cols-1 lg:grid-cols-3 gap-6"><div class="lg:col-span-2"><div class="relative mb-4">'+ic('search','w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-text-secondary')+'<input class="input pl-10" placeholder="Tìm sản phẩm..." id="pos-search" /></div><div class="bg-white rounded-xl border border-border p-4"><div class="grid grid-cols-2 md:grid-cols-3 gap-4 max-h-[600px] overflow-y-auto" id="pos-grid">'+A.mockProducts.map(function(p){var ts=p.variants.reduce(function(s,v){return s+v.stock;},0);return '<button class="text-left border border-border rounded-lg p-3 hover:bg-surface transition-colors '+(ts===0?'opacity-50':'') +'" '+(ts===0?'disabled':'')+' data-pos-add="'+p.id+'"><img src="'+p.images[0]+'" class="w-full aspect-square object-cover rounded mb-2" /><p class="font-medium text-sm mb-1">'+p.name+'</p><p class="text-sm font-semibold text-primary">'+fp(p.salePrice||p.basePrice)+'</p></button>';}).join('')+'</div></div></div><div><div class="bg-white rounded-xl border border-border p-4 mb-4"><h2 class="font-semibold mb-4">Thông tin khách hàng</h2><div class="space-y-3"><div><label class="label">Tên *</label><input class="input" id="pos-name" placeholder="Khách lẻ" /></div><div><label class="label">SĐT *</label><input class="input" id="pos-phone" type="tel" /></div></div></div><div class="bg-white rounded-xl border border-border p-4"><div class="flex items-center justify-between mb-4"><h2 class="font-semibold">Giỏ hàng (<span id="pos-count">0</span>)</h2><button class="btn btn-ghost btn-sm text-error" id="pos-clear">Xóa tất cả</button></div><div class="space-y-3 max-h-[250px] overflow-y-auto mb-4" id="pos-cart-items"><p class="text-center text-text-secondary py-8">Trống</p></div><div class="space-y-2 mb-4 pt-4 border-t"><div class="flex justify-between text-lg font-bold"><span>Tổng:</span><span class="text-accent" id="pos-total">0đ</span></div></div><button class="btn btn-default w-full btn-lg" id="pos-checkout-btn" disabled>'+ic('receipt','w-5 h-5')+' Thanh toán</button></div></div></div></div>';

  A.renderAdmin(content,function(){
    var posCart=[];
    function updateUI(){
      document.getElementById('pos-count').textContent=posCart.length;
      var total=posCart.reduce(function(s,i){return s+i.price*i.quantity;},0);
      document.getElementById('pos-total').textContent=fp(total);
      document.getElementById('pos-checkout-btn').disabled=posCart.length===0;
      var el=document.getElementById('pos-cart-items');
      if(posCart.length===0){el.innerHTML='<p class="text-center text-text-secondary py-8">Trống</p>';return;}
      el.innerHTML=posCart.map(function(i){return '<div class="flex gap-3 pb-3 border-b last:border-0"><img src="'+i.image+'" class="w-14 h-14 object-cover rounded" /><div class="flex-1 min-w-0"><p class="font-medium text-sm">'+i.productName+'</p><p class="text-xs text-text-secondary">'+i.variantLabel+'</p><p class="text-sm font-semibold">'+fp(i.price)+'</p><div class="flex items-center gap-2 mt-1"><button class="btn btn-outline btn-sm" data-pm="'+i.variantId+'">-</button><span class="text-sm w-6 text-center">'+i.quantity+'</span><button class="btn btn-outline btn-sm" data-pp="'+i.variantId+'">+</button><button class="btn btn-ghost btn-sm ml-auto text-error" data-pr="'+i.variantId+'">'+ic('trash-2','w-3 h-3')+'</button></div></div></div>';}).join('');
      A.initIcons(el);
      el.querySelectorAll('[data-pm]').forEach(function(b){b.addEventListener('click',function(){var it=posCart.find(function(x){return x.variantId===b.dataset.pm;});if(it&&it.quantity>1){it.quantity--;updateUI();}});});
      el.querySelectorAll('[data-pp]').forEach(function(b){b.addEventListener('click',function(){var it=posCart.find(function(x){return x.variantId===b.dataset.pp;});if(it&&it.quantity<it.stock){it.quantity++;updateUI();}});});
      el.querySelectorAll('[data-pr]').forEach(function(b){b.addEventListener('click',function(){posCart=posCart.filter(function(x){return x.variantId!==b.dataset.pr;});updateUI();});});
    }
    function bindAdd(){document.querySelectorAll('[data-pos-add]').forEach(function(b){b.addEventListener('click',function(){var p=A.mockProducts.find(function(x){return x.id===b.dataset.posAdd;});if(!p)return;var v=p.variants[0];if(!v||v.stock===0){A.toast.error('Hết hàng');return;}var ex=posCart.find(function(x){return x.variantId===v.id;});if(ex){if(ex.quantity>=v.stock){A.toast.error('Không đủ hàng');return;}ex.quantity++;}else posCart.push({variantId:v.id,productId:p.id,productName:p.name,variantLabel:v.size+' / '+v.color,quantity:1,price:p.salePrice||p.basePrice,image:p.images[0],stock:v.stock});A.toast.success('Đã thêm');updateUI();});});}
    bindAdd();
    document.getElementById('pos-search').addEventListener('input',function(e){var t=e.target.value.toLowerCase();var f=A.mockProducts.filter(function(p){return p.name.toLowerCase().indexOf(t)>=0||p.code.toLowerCase().indexOf(t)>=0;});document.getElementById('pos-grid').innerHTML=f.map(function(p){var ts=p.variants.reduce(function(s,v){return s+v.stock;},0);return '<button class="text-left border border-border rounded-lg p-3 hover:bg-surface transition-colors '+(ts===0?'opacity-50':'')+'" '+(ts===0?'disabled':'')+' data-pos-add="'+p.id+'"><img src="'+p.images[0]+'" class="w-full aspect-square object-cover rounded mb-2" /><p class="font-medium text-sm mb-1">'+p.name+'</p><p class="text-sm font-semibold text-primary">'+fp(p.salePrice||p.basePrice)+'</p></button>';}).join('');bindAdd();});
    document.getElementById('pos-clear').addEventListener('click',function(){posCart=[];updateUI();});
    document.getElementById('pos-checkout-btn').addEventListener('click',function(){
      if(!document.getElementById('pos-name').value||!document.getElementById('pos-phone').value){A.toast.error('Nhập thông tin khách hàng');return;}
      posCart=[];updateUI();document.getElementById('pos-name').value='';document.getElementById('pos-phone').value='';
      A.toast.success('Thanh toán thành công!');
    });
  });
};

// ===== Promotions =====
A.pages.adminPromotions = function(){
  var content='<div><div class="flex justify-between items-center mb-6"><div><h1 class="text-3xl font-bold">Khuyến mãi</h1></div><button class="btn btn-default" id="add-promo-btn">'+ic('plus','w-4 h-4')+' Thêm</button></div><div class="card"><div class="card-content"><div class="table-wrapper"><table class="data-table"><thead><tr><th>Tên</th><th>Mã</th><th>Giảm giá</th><th>Thời gian</th><th>TT</th></tr></thead><tbody>'+A.promotions.map(function(p){return '<tr><td>'+p.name+'</td><td><span class="badge badge-outline font-mono">'+p.code+'</span></td><td>'+(p.type==='percentage'?p.value+'%':fp(p.value))+'</td><td><div class="text-sm">'+fd(p.startDate)+' → '+fd(p.endDate)+'</div></td><td><span class="badge '+(p.status==='active'?'badge-default':'badge-outline')+'">'+(p.status==='active'?'Hoạt động':'Tạm dừng')+'</span></td></tr>';}).join('')+'</tbody></table></div></div></div></div>';
  A.renderAdmin(content,function(){
    document.getElementById('add-promo-btn').addEventListener('click',function(){
      var dc='<div class="dialog-header"><h3 class="dialog-title">Thêm khuyến mãi</h3></div><div class="space-y-4"><div class="grid grid-cols-2 gap-4"><div><label class="label">Tên *</label><input class="input" id="np-name" /></div><div><label class="label">Mã *</label><input class="input" id="np-code" style="text-transform:uppercase" /></div></div><div class="grid grid-cols-2 gap-4"><div><label class="label">Loại</label><select class="custom-select" id="np-type"><option value="percentage">%</option><option value="fixed">VNĐ</option></select></div><div><label class="label">Giá trị *</label><input class="input" type="number" id="np-value" /></div></div><div><label class="label">Mô tả</label><textarea class="input" id="np-desc" rows="2"></textarea></div></div><div class="dialog-footer"><button class="btn btn-outline" data-close>Hủy</button><button class="btn btn-default" id="np-save">Thêm</button></div>';
      var dlg=A.showDialog(dc,{maxWidth:'max-w-2xl'});
      dlg.element.querySelector('#np-save').addEventListener('click',function(){var name=dlg.element.querySelector('#np-name').value;var code=dlg.element.querySelector('#np-code').value.toUpperCase();if(!name||!code){A.toast.error('Nhập tên và mã');return;}A.promotions.push({id:'promo'+Date.now(),name:name,code:code,type:dlg.element.querySelector('#np-type').value,value:parseInt(dlg.element.querySelector('#np-value').value)||0,status:'active',startDate:new Date(),endDate:new Date(),description:dlg.element.querySelector('#np-desc').value});dlg.close();A.toast.success('Đã thêm');A.pages.adminPromotions();});
    });
  });
};

// ===== Staff =====
A.pages.staff = function(){
  var content='<div><div class="flex justify-between items-center mb-6"><div><h1 class="text-3xl font-bold">Nhân viên</h1></div><button class="btn btn-default" id="add-staff-btn">'+ic('plus','w-4 h-4')+' Thêm</button></div><div class="card"><div class="card-content"><div class="table-wrapper"><table class="data-table"><thead><tr><th>Họ tên</th><th>Username</th><th>Email</th><th>SĐT</th><th>TT</th><th class="text-right">Thao tác</th></tr></thead><tbody>'+A.staffAccounts.map(function(s){return '<tr><td>'+s.name+'</td><td class="font-mono">'+s.username+'</td><td>'+s.email+'</td><td>'+s.phone+'</td><td><span class="badge '+(s.status==='active'?'badge-default':'badge-destructive')+'">'+(s.status==='active'?'Hoạt động':'Đã khóa')+'</span></td><td class="text-right"><button class="btn btn-outline btn-sm" data-toggle-staff="'+s.id+'">'+(s.status==='active'?ic('lock','w-4 h-4'):ic('lock-open','w-4 h-4'))+'</button></td></tr>';}).join('')+'</tbody></table></div></div></div></div>';
  A.renderAdmin(content,function(){
    document.querySelectorAll('[data-toggle-staff]').forEach(function(b){b.addEventListener('click',function(){var s=A.staffAccounts.find(function(x){return x.id===b.dataset.toggleStaff;});if(!s)return;var action=s.status==='active'?'Khóa':'Mở khóa';A.showConfirm(action+' tài khoản?',s.name+' sẽ '+(s.status==='active'?'không':'')+ ' thể đăng nhập.',function(){s.status=s.status==='active'?'locked':'active';A.toast.success('Đã '+action.toLowerCase());A.pages.staff();});});});
    document.getElementById('add-staff-btn').addEventListener('click',function(){
      var dc='<div class="dialog-header"><h3 class="dialog-title">Thêm nhân viên</h3></div><div class="space-y-4"><div><label class="label">Họ tên *</label><input class="input" id="ns-name" /></div><div><label class="label">Username *</label><input class="input" id="ns-user" /></div><div><label class="label">Email *</label><input class="input" id="ns-email" type="email" /></div><div><label class="label">SĐT *</label><input class="input" id="ns-phone" /></div></div><div class="dialog-footer"><button class="btn btn-outline" data-close>Hủy</button><button class="btn btn-default" id="ns-save">Thêm</button></div>';
      var dlg=A.showDialog(dc,{maxWidth:'max-w-lg'});
      dlg.element.querySelector('#ns-save').addEventListener('click',function(){var name=dlg.element.querySelector('#ns-name').value;var user=dlg.element.querySelector('#ns-user').value;var email=dlg.element.querySelector('#ns-email').value;var phone=dlg.element.querySelector('#ns-phone').value;if(!name||!user||!email||!phone){A.toast.error('Điền đầy đủ');return;}A.staffAccounts.push({id:'staff'+Date.now(),name:name,username:user,email:email,phone:phone,status:'active',createdAt:new Date()});dlg.close();A.toast.success('Đã thêm');A.pages.staff();});
    });
  });
};

})();
